/**
 * Build identity and deterministic post-bundle instrumentation.
 *
 * Every case runs the shipped CLI (`packages/cli/dist/index.js`, built by
 * `npm run build`) as a child process on real directories: no mocks.
 *
 * The 30-file bundle is generated by the test (`writeBundle`) rather than
 * committed, because what is under test is the order its files are CREATED
 * in, which a checkout cannot fix. It is written twice, in opposite orders,
 * under a tmpfs directory: tmpfs lists a directory's entries newest first,
 * so the two copies list their files in opposite orders (ZFS and ext4 list
 * by a hash of the name, which would hide the difference). The test checks
 * that the listings really differ before relying on it.
 */

import { describe, it, expect, beforeAll, afterAll } from "vitest";
import { spawnSync } from "node:child_process";
import * as crypto from "node:crypto";
import * as fs from "node:fs";
import * as path from "node:path";

import {
  RECORDER_VERSION,
  checkInstrumentedBuild,
  declaredRecorderVersion,
  recorderVersionDeclaration,
} from "@codetracer/instrumenter";
import {
  BUNDLE_MANIFEST_FILE,
  canonicalJson,
  injectBoundaryShim,
} from "@codetracer/boundary-shim";

const REPO_ROOT = path.resolve(__dirname, "..", "..");
const CLI = path.join(REPO_ROOT, "packages", "cli", "dist", "index.js");

/**
 * A directory on tmpfs, whose listing order follows creation order; the
 * test fails (rather than skips) when there is none, since the arms would
 * then not differ in the thing under test.
 */
function tmpfsBase(): string {
  for (const candidate of [process.env.XDG_RUNTIME_DIR, "/dev/shm"]) {
    if (candidate && fs.existsSync(candidate)) {
      const probe = fs.mkdtempSync(path.join(candidate, "ct-jbr-m5-"));
      return probe;
    }
  }
  throw new Error(
    "no tmpfs directory ($XDG_RUNTIME_DIR or /dev/shm) for the creation-order fixture",
  );
}

/**
 * The 30 files of the fixture bundle, by relative path. The names are
 * chosen so that sorting is not trivial: a file and a directory share a
 * stem (`a.js`, `a/…`: a recursive walk visits `a/…` first, the sorted
 * order puts `a.js` first), upper case sorts before lower case, a digit
 * run is not numeric, and one name is not ASCII.
 */
const BUNDLE_FILES: readonly string[] = [
  "a.js",
  "a/inner.js",
  "a/z/deep.js",
  "B.js",
  "assets/index-4f3a.js",
  "assets/vendor-9c1e.js",
  "assets/chunk-10.js",
  "assets/chunk-2.js",
  "assets/chunk-1.js",
  "assets/lazy/route-home.js",
  "assets/lazy/route-cart.js",
  "assets/lazy/route-checkout.js",
  "lib/util.js",
  "lib/format.js",
  "lib/math.js",
  "lib/net/fetcher.js",
  "lib/net/retry.js",
  "lib/net/cache.js",
  "pages/home.js",
  "pages/about.js",
  "pages/Cart.js",
  "pages/checkout/step1.js",
  "pages/checkout/step2.js",
  "pages/checkout/step3.js",
  "widgets/button.js",
  "widgets/modal.js",
  "widgets/tabs.js",
  "zeta.js",
  "ünïcode.js",
  "mapped.js",
];

/** Source of fixture file `i`: two functions, a loop and a branch. */
function moduleSource(rel: string, i: number): string {
  return [
    `// ${rel}`,
    `function f${i}(n) {`,
    `  let total = ${i};`,
    `  for (let k = 0; k < n; k++) {`,
    `    total += k * ${i + 1};`,
    `  }`,
    `  return total;`,
    `}`,
    `function g${i}(s) {`,
    `  if (s.length > ${i % 5}) {`,
    `    return s.toUpperCase();`,
    `  }`,
    `  return s + "${i}";`,
    `}`,
    `globalThis.r${i} = [f${i}(3), g${i}("x")];`,
    ``,
  ].join("\n");
}

/**
 * `mapped.js` stands for bundler output with an external input source map
 * (`mapped.js.map`, naming `../src/mapped.ts`): post-bundle
 * instrumentation reads it and maps steps back through it.
 */
const MAPPED_SOURCE =
  "function mapped(a) {\n  const b = a + 1;\n  return b;\n}\nmapped(1);\n//# sourceMappingURL=mapped.js.map\n";
const MAPPED_MAP = JSON.stringify({
  version: 3,
  file: "mapped.js",
  sources: ["../src/mapped.ts"],
  sourcesContent: [
    "function mapped(a: number): number {\n  const b = a + 1;\n  return b;\n}\nmapped(1);\n",
  ],
  names: [],
  mappings: "AAAA;AACA;AACA;AACA;AACA",
});

/** Write the fixture bundle into `dir`, creating files in `order`. */
function writeBundle(dir: string, order: readonly string[]): void {
  fs.mkdirSync(dir, { recursive: true });
  for (const rel of order) {
    const file = path.join(dir, rel);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    if (rel === "mapped.js") {
      fs.writeFileSync(file, MAPPED_SOURCE);
      fs.writeFileSync(`${file}.map`, MAPPED_MAP);
    } else {
      fs.writeFileSync(file, moduleSource(rel, BUNDLE_FILES.indexOf(rel)));
    }
  }
}

/**
 * Every file under `dir` in the order the filesystem lists it
 * (`fs.opendirSync`, which `collectFiles` reads; `fs.readdirSync` comes
 * back sorted on Unix because libuv's scandir sorts, so it cannot show
 * the difference).
 */
function osListing(dir: string, rel = ""): string[] {
  const out: string[] = [];
  const handle = fs.opendirSync(path.join(dir, rel));
  try {
    for (let e = handle.readSync(); e !== null; e = handle.readSync()) {
      const child = rel === "" ? e.name : `${rel}/${e.name}`;
      if (e.isDirectory()) out.push(...osListing(dir, child));
      else out.push(child);
    }
  } finally {
    handle.closeSync();
  }
  return out;
}

/** Relative path -> sha256 of every file under `dir`. */
function treeDigest(dir: string): Map<string, string> {
  const out = new Map<string, string>();
  for (const rel of osListing(dir).sort()) {
    out.set(
      rel,
      crypto
        .createHash("sha256")
        .update(fs.readFileSync(path.join(dir, rel)))
        .digest("hex"),
    );
  }
  return out;
}

function runCli(args: string[]): {
  status: number | null;
  stdout: string;
  stderr: string;
} {
  if (!fs.existsSync(CLI)) {
    throw new Error(`CLI not built at ${CLI}: run \`npm run build\` first`);
  }
  const r = spawnSync(process.execPath, [CLI, ...args], {
    encoding: "utf-8",
  });
  return { status: r.status, stdout: r.stdout, stderr: r.stderr };
}

let base: string;
beforeAll(() => {
  base = tmpfsBase();
});
afterAll(() => {
  fs.rmSync(base, { recursive: true, force: true });
});

describe("deterministic post-bundle instrumentation", () => {
  it("instrumenting_the_same_bundle_twice_is_byte_identical", () => {
    const dirA = path.join(base, "copy-forward", "dist");
    const dirB = path.join(base, "elsewhere", "copy-reverse", "dist");
    writeBundle(dirA, BUNDLE_FILES);
    writeBundle(dirB, [...BUNDLE_FILES].reverse());

    // Vacuity guard: the two copies list their files in different orders,
    // so the arms differ in the thing under test.
    const listingA = osListing(dirA).filter((p) => p.endsWith(".js"));
    const listingB = osListing(dirB).filter((p) => p.endsWith(".js"));
    expect(listingA).toHaveLength(BUNDLE_FILES.length);
    expect([...listingA].sort()).toEqual([...listingB].sort());
    expect(
      listingA,
      "the filesystem lists both copies in the same order; the test would prove nothing",
    ).not.toEqual(listingB);

    const outA = path.join(base, "out-a");
    const outB = path.join(base, "out-b");
    for (const [src, out] of [
      [dirA, outA],
      [dirB, outB],
    ]) {
      const r = runCli([
        "instrument",
        src,
        "--out",
        out,
        "--relative-paths",
        "--source-maps",
      ]);
      expect(r.status, r.stderr).toBe(0);
      expect(r.stdout).toContain(`Instrumented ${BUNDLE_FILES.length} file(s)`);
    }

    const digestA = treeDigest(outA);
    const digestB = treeDigest(outB);
    // Every file was instrumented, with its map, plus the manifest.
    expect(digestA.size).toBe(BUNDLE_FILES.length * 2 + 1);
    expect([...digestA.keys()]).toEqual([...digestB.keys()]);
    const differing = [...digestA].filter(([rel, h]) => digestB.get(rel) !== h);
    expect(differing.map(([rel]) => rel)).toEqual([]);

    // The manifest names files relative to the bundle root and in sorted
    // order, and resolves mapped.js's steps through its input map.
    const manifest = JSON.parse(
      fs.readFileSync(path.join(outA, "codetracer.manifest.json"), "utf-8"),
    ) as { paths: string[]; recorderVersion: string };
    expect(manifest.recorderVersion).toBe(RECORDER_VERSION);
    for (const p of manifest.paths) {
      expect(path.isAbsolute(p), p).toBe(false);
      expect(p.includes(base), p).toBe(false);
    }
    expect(manifest.paths).toContain("../src/mapped.ts");
    const instrumentedOrder = manifest.paths.filter((p) => p.endsWith(".js"));
    expect(instrumentedOrder[0]).toBe("B.js");
    expect(instrumentedOrder.indexOf("a.js")).toBeLessThan(
      instrumentedOrder.indexOf("a/inner.js"),
    );
    expect(instrumentedOrder.at(-1)).toBe("ünïcode.js");
  });

  it("instrumented_output_declares_recorder_version", () => {
    const src = path.join(base, "version-src");
    writeBundle(src, BUNDLE_FILES);
    const out = path.join(base, "version-out");
    const first = runCli(["instrument", src, "--out", out, "--relative-paths"]);
    expect(first.status, first.stderr).toBe(0);

    // Every instrumented file, and the manifest, declare this version.
    const outputs = osListing(out).filter((p) => p.endsWith(".js"));
    expect(outputs).toHaveLength(BUNDLE_FILES.length);
    for (const rel of outputs) {
      const code = fs.readFileSync(path.join(out, rel), "utf-8");
      expect(declaredRecorderVersion(code), rel).toBe(RECORDER_VERSION);
      expect(code.trimEnd().endsWith(recorderVersionDeclaration()), rel).toBe(
        true,
      );
    }
    const manifestPath = path.join(out, "codetracer.manifest.json");
    const manifestText = fs.readFileSync(manifestPath, "utf-8");
    expect(JSON.parse(manifestText).recorderVersion).toBe(RECORDER_VERSION);
    expect(checkInstrumentedBuild(out)).toEqual([]);

    // Control: a build of the SAME version is reused (instrumenting into
    // it again succeeds and leaves the same bytes).
    const before = treeDigest(out);
    const again = runCli(["instrument", src, "--out", out, "--relative-paths"]);
    expect(again.status, again.stderr).toBe(0);
    expect([...treeDigest(out)]).toEqual([...before]);

    // A build another version made (its files and manifest declare that
    // version) is refused, naming the version, and left untouched.
    const other = path.join(base, "version-other");
    fs.cpSync(out, other, { recursive: true });
    const foreign = "0.0.1-other";
    for (const rel of osListing(other)) {
      const file = path.join(other, rel);
      const text = fs.readFileSync(file, "utf-8");
      fs.writeFileSync(
        file,
        text
          .split(recorderVersionDeclaration())
          .join(recorderVersionDeclaration(foreign))
          .replace(
            `"recorderVersion": "${RECORDER_VERSION}"`,
            `"recorderVersion": "${foreign}"`,
          ),
      );
    }
    expect(checkInstrumentedBuild(other).map((m) => m.declared)).toContain(
      foreign,
    );
    const otherBefore = treeDigest(other);
    const refused = runCli([
      "instrument",
      src,
      "--out",
      other,
      "--relative-paths",
    ]);
    expect(refused.status).toBe(1);
    expect(refused.stderr).toContain("refusing to reuse");
    expect(refused.stderr).toContain(foreign);
    expect(refused.stderr).toContain(RECORDER_VERSION);
    expect([...treeDigest(other)]).toEqual([...otherBefore]);

    // A build that declares no version at all (what this recorder wrote
    // before it declared one) is refused too.
    const undeclared = path.join(base, "version-undeclared");
    fs.cpSync(out, undeclared, { recursive: true });
    const legacy = JSON.parse(manifestText) as Record<string, unknown>;
    delete legacy.recorderVersion;
    fs.writeFileSync(
      path.join(undeclared, "codetracer.manifest.json"),
      JSON.stringify(legacy, null, 2),
    );
    const refusedLegacy = runCli([
      "instrument",
      src,
      "--out",
      undeclared,
      "--relative-paths",
    ]);
    expect(refusedLegacy.status).toBe(1);
    expect(refusedLegacy.stderr).toContain("(none)");
  });
});

describe("bundle manifest and build hash", () => {
  it("bundle_manifest_is_canonical_and_its_hash_survives_the_shim_bootstrap", () => {
    const dist = path.join(base, "site");
    writeBundle(dist, BUNDLE_FILES);
    fs.writeFileSync(
      path.join(dist, "index.html"),
      '<!doctype html>\n<html><head><meta charset="utf-8"><script type="module" src="assets/index-4f3a.js"></script></head><body></body></html>\n',
    );
    fs.writeFileSync(path.join(dist, "assets", "app.css"), "body{margin:0}\n");
    fs.writeFileSync(
      path.join(dist, "assets", "add.wasm"),
      Buffer.from([0, 0x61, 0x73, 0x6d, 1, 0, 0, 0]),
    );
    fs.writeFileSync(path.join(dist, "robots.txt"), "User-agent: *\n");

    const first = runCli(["bundle-manifest", dist]);
    expect(first.status, first.stderr).toBe(0);
    const hash = first.stdout.trim();
    expect(hash).toMatch(/^[0-9a-f]{64}$/);
    const bytes = fs.readFileSync(path.join(dist, BUNDLE_MANIFEST_FILE));
    // The printed hash is the SHA-256 of the written bytes.
    expect(crypto.createHash("sha256").update(bytes).digest("hex")).toBe(hash);
    // Canonical: re-serialising the parsed document gives the same bytes.
    const manifest = JSON.parse(bytes.toString("utf-8")) as {
      files: { path: string; sha256: string; size: number }[];
      version: number;
    };
    expect(canonicalJson(manifest)).toBe(bytes.toString("utf-8"));
    expect(manifest.version).toBe(1);
    const listed = manifest.files.map((f) => f.path);
    // Executable and styling assets only, sorted by UTF-8 bytes.
    expect(listed).toContain("index.html");
    expect(listed).toContain("assets/app.css");
    expect(listed).toContain("assets/add.wasm");
    expect(listed).not.toContain("robots.txt");
    expect(listed).not.toContain("mapped.js.map");
    expect(listed).toEqual(
      [...listed].sort((a, b) =>
        Buffer.compare(Buffer.from(a), Buffer.from(b)),
      ),
    );
    for (const f of manifest.files) {
      const content = fs.readFileSync(path.join(dist, f.path));
      expect(f.size, f.path).toBe(content.length);
      expect(f.sha256, f.path).toBe(
        crypto.createHash("sha256").update(content).digest("hex"),
      );
    }

    // The shim's bootstrap embeds the hash; inserting it does not change
    // the hash (HTML is hashed without the bootstrap).
    const shim = runCli(["boundary-shim", dist, "--build-hash", hash]);
    expect(shim.status, shim.stderr).toBe(0);
    const html = fs.readFileSync(path.join(dist, "index.html"), "utf-8");
    expect(html).toContain(`"buildHash":"${hash}"`);
    const second = runCli(["bundle-manifest", dist]);
    expect(second.status, second.stderr).toBe(0);
    expect(second.stdout.trim()).toBe(hash);
    expect(fs.readFileSync(path.join(dist, BUNDLE_MANIFEST_FILE))).toEqual(
      bytes,
    );

    // Negative control: any other change to a page changes the hash.
    fs.writeFileSync(
      path.join(dist, "index.html"),
      injectBoundaryShim(html.replace("<body>", "<body> "), {
        buildHash: hash,
      }),
    );
    const third = runCli(["bundle-manifest", dist]);
    expect(third.status, third.stderr).toBe(0);
    expect(third.stdout.trim()).not.toBe(hash);
  });

  it("bundle_manifest_refuses_a_symbolic_link_and_an_empty_bundle", () => {
    const empty = path.join(base, "empty-site");
    fs.mkdirSync(empty, { recursive: true });
    fs.writeFileSync(path.join(empty, "notes.txt"), "nothing to run\n");
    const r = runCli(["bundle-manifest", empty]);
    expect(r.status).toBe(1);
    expect(r.stderr).toContain("holds no");

    const linked = path.join(base, "linked-site");
    fs.mkdirSync(linked, { recursive: true });
    fs.writeFileSync(path.join(linked, "app.js"), "1;\n");
    fs.symlinkSync(path.join(linked, "app.js"), path.join(linked, "alias.js"));
    const s = runCli(["bundle-manifest", linked]);
    expect(s.status).toBe(1);
    expect(s.stderr).toContain("neither a regular file nor a directory");
    expect(fs.existsSync(path.join(linked, BUNDLE_MANIFEST_FILE))).toBe(false);
  });
});
